from dataclasses import dataclass

import pytest


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


type Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add and Mul nodes to an int."""
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    if isinstance(e, Mul):
        return eval_expr(e.l) * eval_expr(e.r)
    raise TypeError(f"unknown expression node: {e!r}")


def test_num_leaf() -> None:
    assert eval_expr(Num(7)) == 7


def test_num_negative() -> None:
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(1), Num(2))) == 3


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20


def test_nested_mul_of_add() -> None:
    assert eval_expr(Mul(Add(Num(1), Num(2)), Num(4))) == 12


def test_nested_add_of_mul() -> None:
    assert eval_expr(Add(Mul(Num(2), Num(3)), Mul(Num(4), Num(5)))) == 26


def test_deep_left_chain() -> None:
    e: Expr = Num(1)
    for _ in range(50):
        e = Add(e, Num(1))
    assert eval_expr(e) == 51


def test_zero_multiplication() -> None:
    assert eval_expr(Mul(Num(0), Add(Num(9), Num(9)))) == 0


@pytest.mark.parametrize(
    ("tree", "expected"),
    [
        (Num(0), 0),
        (Add(Num(-1), Num(1)), 0),
        (Mul(Num(-2), Num(-3)), 6),
    ],
)
def test_parametrized(tree: Expr, expected: int) -> None:
    assert eval_expr(tree) == expected
